head.b:skin:
:root{color-scheme:light;--paper:#faf9f7;--ink:#20211f;--muted:#747570;--line:#deded8;--wash:#eeeee8}
:root[data-theme=dark]{color-scheme:dark;--paper:#191a18;--ink:#f0f0e9;--muted:#a7aaa1;--line:#393b35;--wash:#272923}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline;text-underline-offset:5px}button,input{font:inherit}button,summary{cursor:pointer}button{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:2px solid var(--muted);outline-offset:4px}img{max-width:100%;height:auto}button{background:none;border:0} .site{max-width:1100px;width:calc(100% - 80px);margin:auto}.site-header{display:flex;align-items:center;gap:28px;padding:32px 0 40px}.branding{margin-right:auto}.brand{font-size:27px;font-weight:600;letter-spacing:-.8px;line-height:1.2}.subtitle{margin:2px 0 0;font-size:13px;color:var(--muted)}.site-nav{display:flex;gap:28px;align-items:center;font-size:14px}.site-nav a[aria-current=page]{text-decoration:underline;text-underline-offset:9px;text-decoration-thickness:2px}.tools{display:flex;gap:14px;align-items:center}.tool{width:28px;height:32px;padding:4px;display:grid;place-items:center}.tool svg{width:19px;height:19px}.menu{position:relative}.menu summary{list-style:none}.menu summary::-webkit-details-marker{display:none}.menu-panel{position:absolute;right:0;top:38px;z-index:5;min-width:175px;background:var(--paper);border:1px solid var(--line);border-radius:6px;box-shadow:0 8px 30px #0001;padding:14px}.menu-panel a,.menu-panel button{display:block;padding:5px 8px;text-align:left}.search-form{display:flex;gap:12px;align-items:center;padding:0 0 30px}.search-form[hidden]{display:none}.search-form input{min-width:0;flex:1;border:0;border-bottom:1px solid var(--line);padding:10px;background:transparent;color:var(--ink)}.search-form button{padding:9px}.widget,.section{margin:0;padding:0}.post-list{display:grid;gap:24px}.post-card{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:28px;align-items:center;min-width:0}.cover{display:block;overflow:hidden;border-radius:7px;background:var(--wash)}.cover img{display:block;width:100%;aspect-ratio:2.15;object-fit:cover}.card-info{min-width:0}.entry-meta{font-size:14px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap;align-items:center}.post-card .entry-meta{display:block}.labels{display:flex;gap:10px;flex-wrap:wrap}.post-card .labels{margin-top:4px}.post-title{font:400 24px/1.3 Georgia,"Times New Roman",serif;margin:9px 0 13px}.thumbs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.thumbs:empty{display:none}.thumbs img{display:block;width:100%;aspect-ratio:1.05;object-fit:cover;border-radius:5px}.text-cover{display:grid;place-items:center;aspect-ratio:2.15;color:var(--muted);padding:25px;font:italic 23px Georgia,serif}.single #journal{max-width:840px;margin:auto}.single .site-header{padding-bottom:50px}.entry-heading{margin-bottom:16px}.single .post-title{font-size:38px;margin:7px 0 0}.post-body{overflow-wrap:anywhere}.post-body p{margin:0 0 20px}.post-body a{text-decoration:underline;text-underline-offset:3px}.post-body img{max-width:100%!important;height:auto}.post-body iframe,.post-body video{max-width:100%}.post-body pre{overflow:auto}.post-body table{max-width:100%}.post-body .separator{margin:16px 0}.photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:22px 0}.photo-grid>.photo{min-width:0;margin:0!important;padding:0!important;float:none!important;width:auto!important}.photo-grid>.photo:nth-child(3n+1){grid-column:1/-1}.photo-grid .photo>a{display:block;margin:0!important;float:none!important}.photo-grid img{display:block;width:100%!important;height:auto!important;aspect-ratio:1.22;object-fit:cover;border-radius:7px}.photo-grid>.photo:nth-child(3n+1) img{aspect-ratio:1.85}.photo-grid figcaption,.tr-caption{font-size:12px;color:var(--muted);text-align:center}.blog-pager{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:36px 0;font-size:13px}.blog-pager-older-link{margin-left:auto}.home-link{margin:auto}.site-footer{display:flex;justify-content:space-between;gap:20px;padding:18px 0 30px;color:var(--muted);font-size:12px}.archive{border-top:1px solid var(--line);padding:15px 0;margin-top:30px}.archive summary{font-size:13px}.archive .widget{padding:15px 0}.archive ul{padding-left:20px}.status{font-size:14px;color:var(--muted);margin:0 0 25px}.skip-link{position:absolute;top:-100px;left:16px;padding:8px;background:var(--paper);z-index:10}.skip-link:focus{top:10px}[hidden]{display:none!important}.item-control,.blog-feeds{display:none}
@media(min-width:1400px){.site{max-width:1160px}}
@media(max-width:650px){.site{width:calc(100% - 36px)}.site-header{flex-wrap:wrap;gap:22px 12px;padding:27px 0 30px}.brand{font-size:25px}.subtitle{font-size:12px}.site-nav{order:3;width:100%;gap:27px;font-size:13px}.tools{gap:9px}.single .site-header{padding-bottom:40px}.single .site-nav{display:none}.single .subtitle{display:none}.post-list{gap:28px}.post-card{display:block}.card-info{margin-top:9px}.post-card .entry-meta{display:flex;font-size:13px}.post-card .labels{margin:0}.post-card .labels:before{content:'·';margin-right:2px}.post-title{font-size:22px;margin:5px 0 11px}.cover img{aspect-ratio:2.05}.thumbs{gap:9px}.thumbs img{aspect-ratio:1.35}.single .post-title{font-size:32px}.entry-meta{font-size:13px}.post-body{font-size:15px}.photo-grid{gap:10px;margin:20px 0}.photo-grid>.photo:nth-child(3n+1) img{aspect-ratio:1.15}.photo-grid img{aspect-ratio:1}.blog-pager{font-size:12px}.site-footer{font-size:11px}}
@media(prefers-reduced-motion:no-preference){a,button{transition:opacity .15s}a:hover,button:hover{opacity:.8}}

body.script:
(function(){
'use strict';
var root=document.documentElement;
var toggle=document.getElementById('theme-toggle');
function syncTheme(){toggle.textContent=root.dataset.theme==='dark'?'Light mode':'Dark mode';toggle.setAttribute('aria-pressed',String(root.dataset.theme==='dark'));}
syncTheme();
toggle.addEventListener('click',function(){root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('life-theme',root.dataset.theme);}catch(e){}syncTheme();});
var searchButton=document.getElementById('search-toggle'),search=document.getElementById('site-search');
searchButton.addEventListener('click',function(){search.hidden=!search.hidden;searchButton.setAttribute('aria-expanded',String(!search.hidden));if(!search.hidden)search.querySelector('input').focus();});
document.addEventListener('keydown',function(e){if(e.key==='Escape'){if(!search.hidden){search.hidden=true;searchButton.setAttribute('aria-expanded','false');searchButton.focus();}document.querySelectorAll('details.menu[open]').forEach(function(menu){menu.open=false;menu.querySelector('summary').focus();});}});
document.querySelectorAll('time[data-date]').forEach(function(t){var d=new Date(t.dataset.date);if(!isNaN(d.getTime())){t.textContent=new Intl.DateTimeFormat('en',{year:'numeric',month:'short',day:document.body.classList.contains('single')?'numeric':undefined}).format(d);}});
// Read inert post HTML: scripts and embedded media inside templates never execute.
document.querySelectorAll('.post-card').forEach(function(card){var source=card.querySelector('template'),images=Array.from(source.content.querySelectorAll('img')).filter(function(i){return i.getAttribute('src');});var unique=[];images.forEach(function(i){if(!unique.some(function(x){return x.getAttribute('src')===i.getAttribute('src');}))unique.push(i);});var cover=card.querySelector('.cover');if(unique.length&&!cover.querySelector('img')){cover.textContent='';var first=new Image();first.src=unique[0].getAttribute('src');first.alt=unique[0].alt||'';first.loading='lazy';cover.appendChild(first);cover.classList.remove('text-cover');}unique.slice(1,4).forEach(function(original,index){var a=document.createElement('a');a.href=cover.href;a.setAttribute('aria-label',card.querySelector('.post-title').textContent+' — photo '+(index+2));var img=new Image();img.src=original.getAttribute('src');img.alt=original.alt||'';img.loading='lazy';img.decoding='async';a.appendChild(img);card.querySelector('.thumbs').appendChild(a);});source.remove();});
// Group consecutive image-only blocks, leaving prose, captions, tables and embeds intact.
document.querySelectorAll('.post-body').forEach(function(body){var grid=null;Array.from(body.childNodes).forEach(function(node){if(node.nodeType===3&&!node.textContent.trim())return;if(node.nodeType===8)return;if(node.nodeType!==1){grid=null;return;}var imgs=node.matches('img')?[node]:node.querySelectorAll('img');var text=node.textContent.trim();var caption=node.matches('figure')&&node.querySelector('figcaption');var safe=['DIV','P','A','IMG','FIGURE'].includes(node.tagName)&&imgs.length===1&&!node.querySelector('iframe,video,script,table,button,input')&&(!text||(caption&&text===caption.textContent.trim()));if(!safe){if(node.tagName==='BR')return;grid=null;return;}if(!grid){grid=document.createElement('div');grid.className='photo-grid';body.insertBefore(grid,node);}var photo=node;if(node.tagName==='IMG'||node.tagName==='A'){photo=document.createElement('div');node.replaceWith(photo);photo.appendChild(node);}photo.classList.add('photo');grid.appendChild(photo);});});
if(location.hash==='#archive')document.getElementById('archive').open=true;
document.querySelectorAll('a[href="#archive"]').forEach(function(a){a.addEventListener('click',function(){document.getElementById('archive').open=true;});});
})();
